import type { MetadataRoute } from "next";

// Web app manifest: makes paf-ui installable (iOS: Share → Add to Home Screen,
// opens standalone with no Safari chrome). Colors mirror --background in
// app/globals.css (dark). Icons are generated by scripts/gen-icons.py.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "paf",
    short_name: "paf",
    description: "paf-ui — chat over the paf SSE transport",
    id: "/",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0f1115",
    theme_color: "#0f1115",
    icons: [
      // "any": rounded tile with a big wordmark — what desktop installs, launchers
      // and the tab show as-is. Larger sizes give HiDPI desktops a crisp source.
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-256.png", sizes: "256x256", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-1024.png", sizes: "1024x1024", type: "image/png", purpose: "any" },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
